    if H == 1:
        return n
    if H == 2:
        return (n + 1) // 2
    if H == 3:
        return (n + 2) // 3
    if H == 4:
        return (n + 3) // 4
    if H == 5:
        return (n + 4) // 5
    if H == 6:
        return (n + 5) // 6
    if H == 7:
