import sys

def min_spots(n, H):
    if H >= n:
        return 1
    if H == 1:
        return n
    k = (H + 1) // 2
    if n <= k * (k + 1):
        return 2 * k - 1
    else:
        return 2 * k + (n - k * (k + 1)) // (2 * k)

