def min_spots(n, H):
    if n == 1:
        return 1
    if H == 1:
        return n

    # Calculate the minimum number of spots needed
    spots = 0
    current_height = H
    remaining_sand = n

    while remaining_sand > 0:
        spots += 1
        remaining_sand -= current_height
        if current_height > 1:
            current_height -= 1
        else:
            current_height = H

    return spots

